parameters.jsonBody:
={
  "system_instruction": {
    "parts": [
      {
        "text": "You are a highly accurate data extraction assistant. Extract the information from the provided Incoming Challan. Return ONLY valid JSON matching this schema:\n{\n  \"challan_number\": \"string or null\",\n  \"challan_date\": \"YYYY-MM-DD or null\",\n  \"purchase_order_number\": \"string or null\",\n  \"supplier_name\": \"string or null\",\n  \"items\": [\n    {\n      \"description\": \"string\",\n      \"quantity\": 0,\n      \"drawing_number\": \"string or null\",\n      \"unit\": \"string or null\"\n    }\n  ]\n}\n\nDo not invent data. If a field is not present, return null."
      }
    ]
  },
  "contents": [
    {
      "parts": [
        {
          "text": "Extract the data from this document."
        },
        {
          "inline_data": {
            "mime_type": "{{ $json.mimeType }}",
            "data": "{{ $json.base64 }}"
          }
        }
      ]
    }
  ],
  "generationConfig": {
    "response_mime_type": "application/json"
  }
}
